#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAX_BITS 31

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }
    const char *src = argv[1];
    size_t len = strlen(src);
    if (len == 0 || len > MAX_BITS) {
        puts("INVALID_INPUT");
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        if (src[i] != '0' && src[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }
    char tape[MAX_BITS];
    memcpy(tape, src, len);
    int steps = 0;
    bool overflow = true;
    for (size_t i = 0; i < len; ++i) {
        ++steps;
        if (tape[i] == '0') {
            tape[i] = '1';
            overflow = false;
            break;
        } else {
            tape[i] = '0';
        }
    }
    if (overflow) {
        puts("OVERFLOW");
    } else {
        printf("result=");
        for (size_t i = 0; i < len; ++i) putchar(tape[i]);
        putchar('\n');
    }
    printf(" steps=%d\n", steps);
    return 0;
}
